#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/skbuff.h>
#include <linux/filter.h>

static int __init check_offsets_init(void)
{
    pr_info("OFFSET: struct sk_buff, data: %lu\n", offsetof(struct sk_buff, data));
    pr_info("OFFSET: struct sk_buff, tail: %lu\n", offsetof(struct sk_buff, tail));
    pr_info("OFFSET: struct sk_buff, cb: %lu\n", offsetof(struct sk_buff, cb));
    pr_info("OFFSET: struct sk_buff, len: %lu\n", offsetof(struct sk_buff, len));
    pr_info("OFFSET: struct bpf_skb_data_end, data_end: %lu\n", offsetof(struct bpf_skb_data_end, data_end));
    return 0;
}

static void __exit check_offsets_exit(void)
{
}

module_init(check_offsets_init);
module_exit(check_offsets_exit);
MODULE_LICENSE("GPL");

